class Solution:
    def reverseList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        prev, cur = None, head
        while cur:
            nxt = cur.next              # 先记住下一个
            cur.next = prev             # 箭头掉头
            prev = cur
            cur = nxt
        return prev

